inline bool CorrectAnarkRenderBinding(uint32_t model, uint32_t& hash,
                                      double& su, double& sv, double& u, double& v) {
  const double input[] = {su, sv, u, v};
  for (const auto& rule : kAnarkRenderBindings) {
    if (rule.model != model || rule.hash != hash) continue;
    bool matches = true;
    for (unsigned i = 0; i < 4; ++i)
      matches &= std::isfinite(input[i]) && std::abs(input[i] - rule.before[i]) < 0.000001;
    if (!matches) continue;
    hash = 222321799u; // art\\gui\\persistant\\abyx.tex, bank name hash
    su = rule.after[0]; sv = rule.after[1];
    u = rule.after[2]; v = rule.after[3];
    return true;
  }
  return false;
}
